import numpy as np
from scipy import stats
from sklearn.linear_model import LogisticRegression
from sklearn.feature_selection import mutual_info_classif
from collections import defaultdict

MAX_DRIVERS = 5

def design(feats):
    # Identify strong candidates based on effect size and statistical significance
    strong_candidates = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] in ('copy_number', 'expression', 'derived'):
            t_stat = feats.x[:, i].dot(feats.y - feats.y.mean()) / (
                np.std(feats.x[:, i]) * np.std(feats.y) + 1e-8)
            if abs(t_stat) > 2.0 and abs(feats.y.mean() - np.mean(feats.x[:, i][feats.y==1])) > 0.1:
                strong_candidates.append((fid, abs(t_stat)))

    # Sort by strength
    strong_candidates.sort(key=lambda x: x[1], reverse=True)

    # Remove near-duplicates (correlated features)
    selected_features = set()
    correlated_pairs = set()

    # Build correlation matrix to identify near-duplicates
    corr_matrix = np.corrcoef(feats.x.T)
    for i in range(len(feats.ids)):
        for j in range(i+1, len(feats.ids)):
            if abs(corr_matrix[i,j]) >= 0.6:
                fid_i, fid_j = feats.ids[i], feats.ids[j]
                correlated_pairs.add((min(fid_i, fid_j), max(fid_i, fid_j)))

    # Select non-correlated features
    drivers = []
    for fid, _ in strong_candidates[:MAX_DRIVERS]:
        # Check if this feature is correlated with any already selected feature
        is_correlated = False
        for sel_fid in drivers:
            if (min(sel_fid, fid), max(sel_fid, fid)) in correlated_pairs:
                is_correlated = True
                break

        if not is_correlated:
            drivers.append(fid)
            if len(drivers) >= MAX_DRIVERS:
                break

    # Use all features that are not highly correlated with each other
    columns = list(set(drivers))

    # Create products between top features
    products = []
    for i in range(min(3, len(drivers))):
        for j in range(i+1, min(3, len(drivers))):
            products.append((drivers[i], drivers[j]))

    # Simple weighted score using top features
    loadings = {}
    for i, fid in enumerate(drivers):
        loadings[fid] = np.abs(np.corrcoef(feats.x[:, i], feats.y)[0,1])

    return Design(
        drivers=tuple(drivers),
        columns=tuple(columns),
        products=tuple(products),
        loadings=loadings
    )

